import unittest
from candidate import total_match

class TestTotalMatch(unittest.TestCase):
    def test_total_match_empty_lists(self):
        self.assertEqual(total_match([], []), [])

    def test_total_match_first_list_shorter(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hi', 'admin'])

    def test_total_match_second_list_shorter(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])

    def test_total_match_equal_length_lists(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'hi', 'hi']), ['hi', 'admin'])

    def test_total_match_single_element_lists(self):
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_total_match_none_inputs(self):
        with self.assertRaises(TypeError):
            total_match(None, ['1', '2'])
        with self.assertRaises(TypeError):
            total_match(['1', '2'], None)

    def test_total_match_non_list_inputs(self):
        with self.assertRaises(TypeError):
            total_match('abc', ['1', '2'])
        with self.assertRaises(TypeError):
            total_match(['1', '2'], 'abc')

    def test_total_match_mixed_type_lists(self):
        with self.assertRaises(TypeError):
            total_match(['1', 2], ['a', 'b'])
        with self.assertRaises(TypeError):
            total_match(['1', '2'], ['a', 2])

if __name__ == '__main__':
    unittest.main()
